                  <div style={{fontSize:10,fontFamily:"'DM Mono',monospace",display:"flex",gap:5}}>
                    <span style={{color:"var(--accent2)",fontWeight:700}}>{getTeam(p.pid, p.team)}</span>
                  </div>
