// ── ODDS CALCULATOR SLIDEOUT ──────────────────────────────────────────────────
const CALC_CURRENCIES = ['USD','EUR','GBP','CAD','AUD','JPY'];
const CALC_CCY_SYM = {USD:'$',EUR:'€',GBP:'£',CAD:'CA$',AUD:'A$',JPY:'¥'};
function calcFmtCcy(n, ccy) {
  if (n == null || isNaN(n)) return '—';
  return (CALC_CCY_SYM[ccy] || '$') + Number(n).toLocaleString('en-US',
    {minimumFractionDigits:2, maximumFractionDigits:2});
}
function calcAmToDecimal(a) {
  return a > 0 ? (a / 100) + 1 : (100 / Math.abs(a)) + 1;
}
function calcDecToAmerican(d) {
  return d >= 2 ? Math.round((d - 1) * 100) : Math.round(-100 / (d - 1));
}
function calcParseOdds(raw) {
  const s = (raw || '').trim();
  if (!s) return null;
  if (s.startsWith('+') || s.startsWith('-')) {
    const a = parseFloat(s);
    if (isNaN(a) || Math.abs(a) < 100) return null;
    return { american: a, decimal: +calcAmToDecimal(a).toFixed(4) };
  }
  if (s.includes('.')) {
    const d = parseFloat(s);
    if (isNaN(d) || d <= 1) return null;
    return { american: calcDecToAmerican(d), decimal: d };
  }
  const n = parseFloat(s);
  if (isNaN(n)) return null;
  if (n >= 100) return { american: n, decimal: +calcAmToDecimal(n).toFixed(4) };
  if (n > 1)    return { american: calcDecToAmerican(n), decimal: n };
  return null;
}

// ── Round Robin — all size-K combinations of leg indices [0..n-1] ───────────
// Standard round robin math: every combo of K legs becomes its own separate
// parlay with an equal stake. Needs only K (not all N) legs to hit to pay out
// that specific line — the whole point vs a straight N-leg parlay.
function rrCombinations(n, k) {
  const idx = Array.from({length:n}, (_,i)=>i);
  const out = [];
  const build = (start, combo) => {
    if (combo.length === k) { out.push([...combo]); return; }
    for (let i = start; i < idx.length; i++) {
      combo.push(idx[i]);
      build(i+1, combo);
      combo.pop();
    }
  };
  build(0, []);
  return out;
}

function OddsCalculatorSlideout({ onClose }) {
  const mono = "'DM Mono',monospace", osw = "'Oswald',sans-serif";
  const [mode,      setMode]      = useState('manual');
  const [oddsRaw,   setOddsRaw]   = useState('');
  const [bankroll,  setBankroll]  = useState('');
  const [unitSize,  setUnitSize]  = useState('');
  const [unitRate,  setUnitRate]  = useState(3.0);
  const [sugFrac,   setSugFrac]   = useState('');
  const [showScale, setShowScale] = useState(false);
  const [currency,  setCurrency]  = useState('USD');
  const [result,    setResult]    = useState(null);

  // ── Parlay tab state — shares bankroll/unitSize/unitRate with Manual mode.
  // Any pick count (2+) computes a straight full-leg parlay (parlayResult).
  // "Enable Round Robin" is an add-on, only available at 3+ picks — it
  // additionally breaks the same legs into every combo of a chosen size
  // (rrResult), it does not gate the base parlay calculation. ──
  const [rrPickNum,       setRrPickNum]       = useState(2);
  const [rrEnabled,       setRrEnabled]       = useState(false);
  const [rrComboSize,     setRrComboSize]     = useState(2);
  const [rrOddsRaw,       setRrOddsRaw]       = useState(['', '']);
  const [parlayResult,    setParlayResult]    = useState(null);
  const [rrResult,        setRrResult]        = useState(null);

  const parsed  = calcParseOdds(oddsRaw);
  const sym     = CALC_CCY_SYM[currency] || '$';
  const rateNum = parseFloat(unitRate) || 3;

  const computeSugFrac = p => {
    if (!p) return 1;
    const am = p.american;
    const raw = am > 0 ? 100 / am : Math.min(1.5, Math.abs(am) / 100);
    return Math.max(raw, 0.05);
  };
  const fmtFrac = n => parseFloat(n.toFixed(3)).toString();

  const handleBankroll = v => {
    setBankroll(v);
    const b = parseFloat(v), r = rateNum / 100;
    setUnitSize((!isNaN(b) && b > 0) ? (b * r).toFixed(2) : '');
    setResult(null);
    setRrResult(null);
  };
  const handleUnitSize = v => {
    setUnitSize(v);
    const u = parseFloat(v), r = rateNum / 100;
    setBankroll((!isNaN(u) && u > 0) ? (u / r).toFixed(2) : '');
    setResult(null);
    setRrResult(null);
  };
  const handleUnitRate = v => {
    setUnitRate(v);
    const r = (parseFloat(v) || 3) / 100;
    const b = parseFloat(bankroll), u = parseFloat(unitSize);
    if (!isNaN(b) && b > 0) setUnitSize((b * r).toFixed(2));
    else if (!isNaN(u) && u > 0) setBankroll((u / r).toFixed(2));
    setResult(null);
    setRrResult(null);
  };

  const handleOddsChange = v => {
    setOddsRaw(v);
    setResult(null);
    if (mode === 'suggested') {
      const p = calcParseOdds(v);
      if (p) setSugFrac(fmtFrac(computeSugFrac(p)));
    }
  };

  const handleModeSwitch = m => {
    setMode(m);
    setResult(null);
    if (m === 'suggested' && parsed) setSugFrac(fmtFrac(computeSugFrac(parsed)));
  };

  const riskDesc = frac => {
    if (frac >= 1.0)   return 'Full unit (Favorite)';
    if (frac >= 0.75)  return 'Standard play';
    if (frac >= 0.50)  return 'Half unit';
    if (frac >= 0.25)  return 'Quarter unit';
    if (frac >= 0.125) return 'Micro-fractional (Longshot)';
    return 'Minimum stake (Extreme longshot)';
  };

  const canCalc = !!(parsed && parsed.decimal > 1 && parseFloat(unitSize) > 0);

  const calculate = () => {
    if (!canCalc) return;
    const dec           = parsed.decimal;
    const fullUnitValue = parseFloat(unitSize);
    let unitFrac;
    if (mode === 'suggested') {
      unitFrac = Math.max(parseFloat(sugFrac) || computeSugFrac(parsed), 0.05);
    } else {
      unitFrac = 1 / (dec - 1);
    }
    const estStake  = Math.max(unitFrac * fullUnitValue, 0.10);
    const potReturn = estStake * dec;
    setResult({ fullUnitValue, unitFrac, estStake, potReturn,
                impliedProb: (1 / dec) * 100,
                profit: potReturn - estStake,
                desc: riskDesc(unitFrac) });
  };

  // ── Parlay / Round Robin ────────────────────────────────────────────────
  const rrComboSizeOptions = Array.from({length: Math.max(0, rrPickNum - 2)}, (_,i) => i + 2); // 2..N-1

  const handleRrPickNum = v => {
    const n = Math.max(2, Math.min(5, parseInt(v) || 2));
    setRrPickNum(n);
    setRrOddsRaw(prev => {
      const next = [...prev];
      while (next.length < n) next.push('');
      return next.slice(0, n);
    });
    if (n < 3) setRrEnabled(false);
    setRrComboSize(2);
    setParlayResult(null);
    setRrResult(null);
  };
  const handleRrOddsChange = (i, v) => {
    setRrOddsRaw(prev => { const next = [...prev]; next[i] = v; return next; });
    setParlayResult(null);
    setRrResult(null);
  };
  const rrParsedOdds = rrOddsRaw.map(o => calcParseOdds(o));
  // Valid for a straight parlay at ANY pick count (2+) — independent of the
  // Round Robin checkbox, which only adds the combo breakdown on top.
  const rrAllOddsValid = rrPickNum >= 2 && rrParsedOdds.length === rrPickNum
    && rrParsedOdds.every(p => p && p.decimal > 1);
  const rrCanCalc = rrAllOddsValid && parseFloat(unitSize) > 0;

  // Suggested stake fraction for a given combined decimal odds value (used
  // for both the straight parlay and each round-robin combo line). Same
  // anchor as Suggested mode's computeSugFrac (~1 unit profit, 0.05u floor
  // for longshots) — but parlay/round-robin odds can compound multiple
  // longshot legs into odds far beyond anything a single bet would show,
  // where a flat 0.05u floor can suggest a payout many multiples of the
  // whole bankroll. Second ceiling: if even the floor stake's payout would
  // exceed the full bankroll, shrink the stake further so payout caps at
  // exactly 1 bankroll instead.
  const computeSugFracFromDecimal = (dec, bankrollVal, unitVal) => {
    const rawFrac = 1 / Math.max(dec - 1, 0.0001);
    let frac = Math.max(rawFrac, 0.05);
    if (bankrollVal > 0 && unitVal > 0) {
      const floorPayout = frac * unitVal * dec;
      if (floorPayout > bankrollVal) frac = (bankrollVal / dec) / unitVal;
    }
    return Math.max(frac, 0.001);
  };

  const calculateRR = () => {
    if (!rrCanCalc) return;
    const unitVal     = parseFloat(unitSize);
    const bankrollVal = parseFloat(bankroll) || 0;

    // ── Straight parlay — all N legs combined into one bet. Computed for
    // any pick count, regardless of the Round Robin checkbox. ──
    const parlayDec    = rrParsedOdds.reduce((p, o) => p * o.decimal, 1);
    const parlayFrac   = computeSugFracFromDecimal(parlayDec, bankrollVal, unitVal);
    const parlayStake  = Math.max(parlayFrac * unitVal, 0.10);
    const parlayPayout = parlayStake * parlayDec;
    setParlayResult({
      decimal: parlayDec, american: calcDecToAmerican(parlayDec),
      frac: parlayFrac, stake: parlayStake, payout: parlayPayout,
      profit: parlayPayout - parlayStake, desc: riskDesc(parlayFrac),
    });

    // ── Round Robin combo breakdown — add-on, only when enabled + 3+ picks ──
    if (rrEnabled && rrPickNum >= 3 && rrComboSize >= 2 && rrComboSize <= rrPickNum - 1) {
      const combos = rrCombinations(rrPickNum, rrComboSize).map(legIdxs => {
        const dec   = legIdxs.reduce((p, i) => p * rrParsedOdds[i].decimal, 1);
        const frac  = computeSugFracFromDecimal(dec, bankrollVal, unitVal);
        const stake = Math.max(frac * unitVal, 0.10);
        const payout = stake * dec;
        return { legIdxs, decimal: dec, frac, stake, payout,
                 profit: payout - stake, desc: riskDesc(frac) };
      });
      const totalStake  = combos.reduce((s, c) => s + c.stake, 0);
      const maxPayout    = combos.reduce((s, c) => s + c.payout, 0);
      const floorCombo   = combos.reduce((min, c) => c.payout < min.payout ? c : min, combos[0]);
      const ceilCombo     = combos.reduce((max, c) => c.payout > max.payout ? c : max, combos[0]);
      setRrResult({
        combos, totalStake, maxPayout,
        maxProfit: maxPayout - totalStake,
        floorPayout: floorCombo.payout,
        ceilPayout: ceilCombo.payout,
      });
    } else {
      setRrResult(null);
    }
  };

  const inpStyle = {flex:1,background:'var(--surface2)',border:'1px solid var(--border)',
    borderRadius:6,padding:'7px 10px',fontFamily:mono,fontSize:13,color:'var(--text)',
    outline:'none',minWidth:0,WebkitAppearance:'none'};
  const lblStyle = {fontSize:9,color:'var(--muted)',fontFamily:mono,
    textTransform:'uppercase',letterSpacing:1,marginBottom:6,display:'block'};

  const SCALE_ROWS = [
    ['-150 or heavier', '1.0u – 1.5u'],
    ['-110 to +110',    '1.0u (baseline)'],
    ['+115 to +175',    '~0.75u'],
    ['+180 to +275',    '~0.50u'],
    ['+300 to +490',    '~0.25u'],
    ['+500 to +900',    '~0.125u'],
    ['+1000 or longer', '0.05u (floor)'],
  ];

  return <>
    <div onClick={onClose} style={{position:'fixed',inset:0,background:'rgba(0,0,0,.55)',zIndex:900}}/>
    <div style={{position:'fixed',right:0,top:0,bottom:0,width:'min(380px,100vw)',
      background:'var(--surface)',borderLeft:'1px solid var(--border)',zIndex:901,
      display:'flex',flexDirection:'column',boxShadow:'-4px 0 24px rgba(0,0,0,.5)'}}>
      {/* ── Header ── */}
      <div style={{padding:'14px 18px',borderBottom:'1px solid var(--border)',
        display:'flex',alignItems:'center',gap:8,flexShrink:0,background:'var(--surface2)'}}>
        <span style={{fontFamily:osw,fontWeight:700,fontSize:15,letterSpacing:.5,
          color:'var(--text)'}}>🧮 Odds Calculator</span>
        <button onClick={onClose} style={{marginLeft:'auto',background:'none',
          border:'1px solid var(--border)',borderRadius:6,color:'var(--muted)',
          cursor:'pointer',padding:'3px 9px',fontFamily:mono,fontSize:11}}>✕</button>
      </div>
      <div style={{flex:1,overflowY:'auto',padding:'16px 18px'}}>
        {/* ── Mode Toggle ── */}
        <div style={{display:'flex',gap:3,marginBottom:18,background:'var(--surface2)',
          borderRadius:8,padding:3,border:'1px solid var(--border)'}}>
          {[['manual','Manual'],['suggested','Suggested'],['roundrobin','Parlay']].map(([m, label]) => (
            <button key={m} onClick={()=>handleModeSwitch(m)}
              style={{flex:1,padding:'5px 0',borderRadius:6,border:'none',cursor:'pointer',
                fontFamily:mono,fontSize:10,fontWeight:mode===m?700:400,letterSpacing:.5,
                textTransform:'uppercase',
                background:mode===m?'var(--accent)':'transparent',
                color:mode===m?'white':'var(--muted)',transition:'all .15s'}}>
              {label}
            </button>
          ))}
        </div>

        {/* ── Odds (single-bet modes only — Round Robin has its own per-leg inputs) ── */}
        {mode !== 'roundrobin' && (
        <div style={{marginBottom:18}}>
          <span style={lblStyle}>Odds Input</span>
          <input value={oddsRaw} onChange={e=>handleOddsChange(e.target.value)}
            placeholder="+180  ·  −150  ·  2.80"
            style={{width:'100%',boxSizing:'border-box',background:'var(--surface2)',
              border:'1px solid var(--border)',borderRadius:6,padding:'9px 12px',
              fontFamily:mono,fontSize:14,color:'var(--text)',outline:'none'}}/>
          <div style={{marginTop:8,minHeight:34}}>
            {parsed ? (
              <div style={{display:'flex',gap:8}}>
                <div style={{flex:1,background:'rgba(56,184,242,.08)',
                  border:'1px solid rgba(56,184,242,.25)',borderRadius:6,
                  padding:'5px 10px',textAlign:'center'}}>
                  <span style={{fontFamily:mono,fontSize:9,color:'var(--muted)',display:'block'}}>AMERICAN</span>
                  <span style={{fontFamily:osw,fontWeight:700,fontSize:15,color:'#38b8f2'}}>
                    {parsed.american >= 0 ? '+' : ''}{parsed.american}
                  </span>
                </div>
                <div style={{flex:1,background:'rgba(245,166,35,.08)',
                  border:'1px solid rgba(245,166,35,.25)',borderRadius:6,
                  padding:'5px 10px',textAlign:'center'}}>
                  <span style={{fontFamily:mono,fontSize:9,color:'var(--muted)',display:'block'}}>DECIMAL</span>
                  <span style={{fontFamily:osw,fontWeight:700,fontSize:15,color:'#f5a623'}}>
                    {parsed.decimal.toFixed(2)}
                  </span>
                </div>
                <div style={{flex:1,background:'rgba(56,242,130,.08)',
                  border:'1px solid rgba(56,242,130,.25)',borderRadius:6,
                  padding:'5px 10px',textAlign:'center'}}>
                  <span style={{fontFamily:mono,fontSize:9,color:'var(--muted)',display:'block'}}>IMPLIED</span>
                  <span style={{fontFamily:osw,fontWeight:700,fontSize:15,color:'#38f282'}}>
                    {(100/parsed.decimal).toFixed(1)}%
                  </span>
                </div>
              </div>
            ) : oddsRaw ? (
              <div style={{fontFamily:mono,fontSize:11,color:'var(--accent)',padding:'4px 0'}}>
                Enter American (+180, -150) or decimal (2.80) odds
              </div>
            ) : null}
          </div>
        </div>
        )}

        {/* ── Currency ── */}
        <div style={{marginBottom:18}}>
          <span style={lblStyle}>Currency</span>
          <div style={{display:'flex',gap:4,flexWrap:'wrap'}}>
            {CALC_CURRENCIES.map(c => (
              <button key={c} onClick={()=>setCurrency(c)}
                style={{padding:'4px 10px',borderRadius:5,border:'1px solid var(--border)',
                  background:currency===c?'var(--accent)':'var(--surface2)',
                  color:currency===c?'white':'var(--muted)',
                  fontFamily:mono,fontSize:10,cursor:'pointer',fontWeight:currency===c?700:400}}>
                {c}
              </button>
            ))}
          </div>
        </div>

        {/* ── Bankroll / Unit (Manual) or Unit Size (Suggested) ── */}
        {mode === 'roundrobin' ? (
          <>
            {/* ── Bankroll / Unit — same shared state as Manual mode, carries over ── */}
            <div style={{marginBottom:14}}>
              <span style={lblStyle}>Bankroll ({sym})</span>
              <div style={{display:'flex',gap:8,alignItems:'center'}}>
                <input value={bankroll} onChange={e=>handleBankroll(e.target.value)}
                  placeholder="e.g. 1000" type="number" min="0" style={inpStyle}/>
              </div>
            </div>
            <div style={{marginBottom:14}}>
              <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:6}}>
                <span style={{...lblStyle,marginBottom:0}}>Unit Size ({sym})</span>
                <div style={{display:'flex',alignItems:'center',gap:5}}>
                  <span style={{fontFamily:mono,fontSize:9,color:'var(--muted)'}}>% of bankroll:</span>
                  <input value={unitRate} onChange={e=>handleUnitRate(e.target.value)}
                    type="number" min="0.1" max="100" step="0.5"
                    style={{width:48,background:'var(--surface2)',border:'1px solid var(--border)',
                      borderRadius:4,padding:'3px 6px',fontFamily:mono,fontSize:11,
                      color:'var(--text)',outline:'none',textAlign:'right'}}/>
                  <span style={{fontFamily:mono,fontSize:9,color:'var(--muted)'}}>%</span>
                </div>
              </div>
              <input value={unitSize} onChange={e=>handleUnitSize(e.target.value)}
                placeholder="e.g. 30" type="number" min="0" style={{...inpStyle,flex:'unset',width:'100%',boxSizing:'border-box'}}/>
            </div>

            {/* ── Pick Number ── */}
            <div style={{marginBottom:14}}>
              <span style={lblStyle}>Pick Number</span>
              <select value={rrPickNum} onChange={e=>handleRrPickNum(e.target.value)}
                style={{...inpStyle,flex:'unset',width:'100%',boxSizing:'border-box',
                  appearance:'auto',cursor:'pointer'}}>
                {[2,3,4,5].map(n => <option key={n} value={n}>{n} picks</option>)}
              </select>
            </div>

            {/* ── Enable Round Robin checkbox — disabled below 3 picks. This
                only ADDS the combo breakdown below; the straight parlay
                calculation works at any pick count regardless of this. ── */}
            <label style={{display:'flex',alignItems:'center',gap:8,marginBottom:14,
              cursor:rrPickNum>=3?'pointer':'not-allowed',opacity:rrPickNum>=3?1:.45}}>
              <input type="checkbox" checked={rrEnabled}
                disabled={rrPickNum<3}
                onChange={e=>{ setRrEnabled(e.target.checked); setRrResult(null); }}
                style={{width:16,height:16,cursor:rrPickNum>=3?'pointer':'not-allowed'}}/>
              <span style={{fontFamily:mono,fontSize:11,color:'var(--text)'}}>
                Enable Round Robin
              </span>
              {rrPickNum<3 && (
                <span style={{fontFamily:mono,fontSize:9,color:'var(--muted)'}}>
                  (select 3+ picks)
                </span>
              )}
            </label>

            {/* ── Combo Size — round robin add-on only ── */}
            {rrEnabled && rrPickNum>=3 && (
              <div style={{marginBottom:14}}>
                <span style={lblStyle}>Combo Size (legs per line)</span>
                <select value={rrComboSize}
                  onChange={e=>{ setRrComboSize(parseInt(e.target.value)); setRrResult(null); }}
                  style={{...inpStyle,flex:'unset',width:'100%',boxSizing:'border-box',
                    appearance:'auto',cursor:'pointer'}}>
                  {rrComboSizeOptions.map(k => (
                    <option key={k} value={k}>
                      {k === 2 ? 'Doubles' : k === 3 ? 'Trebles' : `${k}-leg combos`} — {rrCombinations(rrPickNum,k).length} lines
                    </option>
                  ))}
                </select>
              </div>
            )}

            {/* ── Per-leg odds — always shown at 2+ picks, independent of
                the Round Robin checkbox ── */}
            <div style={{marginBottom:14}}>
              <span style={lblStyle}>Odds — each pick</span>
              {rrOddsRaw.map((o, i) => {
                const p = calcParseOdds(o);
                return (
                  <div key={i} style={{display:'flex',alignItems:'center',gap:8,marginBottom:6}}>
                    <span style={{fontFamily:mono,fontSize:10,color:'var(--muted)',width:14}}>{i+1}</span>
                    <input value={o} onChange={e=>handleRrOddsChange(i, e.target.value)}
                      placeholder="+180  ·  −150  ·  2.80"
                      style={{...inpStyle,fontSize:12}}/>
                    <span style={{fontFamily:mono,fontSize:10,width:44,textAlign:'right',
                      color:p?'#38f282':'var(--muted)'}}>
                      {p ? p.decimal.toFixed(2) : '—'}
                    </span>
                  </div>
                );
              })}
            </div>
            <div style={{fontFamily:mono,fontSize:9,color:'var(--muted)',marginBottom:2}}>
              {rrEnabled && rrPickNum>=3
                ? 'Straight parlay below uses all picks together. Each round robin line below gets its own suggested stake — same ~1 unit profit target as Suggested mode, capped at 1 full bankroll for extreme odds.'
                : 'Suggested stake sized to the same ~1 unit profit target as Suggested mode, capped at 1 full bankroll for extreme odds.'}
            </div>
          </>
        ) : mode === 'manual' ? (
          <>
            <div style={{marginBottom:14}}>
              <span style={lblStyle}>Bankroll ({sym})</span>
              <div style={{display:'flex',gap:8,alignItems:'center'}}>
                <input value={bankroll} onChange={e=>handleBankroll(e.target.value)}
                  placeholder="e.g. 1000" type="number" min="0" style={inpStyle}/>
              </div>
            </div>
            <div style={{marginBottom:14}}>
              <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:6}}>
                <span style={{...lblStyle,marginBottom:0}}>Unit Size ({sym})</span>
                <div style={{display:'flex',alignItems:'center',gap:5}}>
                  <span style={{fontFamily:mono,fontSize:9,color:'var(--muted)'}}>% of bankroll:</span>
                  <input value={unitRate} onChange={e=>handleUnitRate(e.target.value)}
                    type="number" min="0.1" max="100" step="0.5"
                    style={{width:48,background:'var(--surface2)',border:'1px solid var(--border)',
                      borderRadius:4,padding:'3px 6px',fontFamily:mono,fontSize:11,
                      color:'var(--text)',outline:'none',textAlign:'right'}}/>
                  <span style={{fontFamily:mono,fontSize:9,color:'var(--muted)'}}>%</span>
                </div>
              </div>
              <input value={unitSize} onChange={e=>handleUnitSize(e.target.value)}
                placeholder="e.g. 30" type="number" min="0" style={{...inpStyle,flex:'unset',width:'100%',boxSizing:'border-box'}}/>
            </div>
          </>
        ) : (
          <>
            <div style={{marginBottom:14}}>
              <span style={lblStyle}>Unit Size ({sym})</span>
              <input value={unitSize} onChange={e=>{ setUnitSize(e.target.value); setResult(null); }}
                placeholder="e.g. 30" type="number" min="0"
                style={{...inpStyle,flex:'unset',width:'100%',boxSizing:'border-box'}}/>
            </div>
            <div style={{marginBottom:14}}>
              <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:6}}>
                <span style={{...lblStyle,marginBottom:0}}>Suggested fraction</span>
                <button onClick={()=>setShowScale(s=>!s)}
                  style={{fontFamily:mono,fontSize:9,color:'var(--accent)',background:'none',
                    border:'none',cursor:'pointer',padding:0,textDecoration:'underline'}}>
                  {showScale ? 'hide scale' : 'show scale'}
                </button>
              </div>
              <input value={sugFrac} onChange={e=>{ setSugFrac(e.target.value); setResult(null); }}
                placeholder="e.g. 0.5" type="number" min="0.05" max="2" step="0.05" style={inpStyle}/>
              {showScale && (
                <div style={{marginTop:10,borderRadius:6,overflow:'hidden',
                  border:'1px solid var(--border)'}}>
                  <table style={{width:'100%',borderCollapse:'collapse',fontFamily:mono,fontSize:10}}>
                    <thead>
                      <tr style={{background:'var(--surface2)'}}>
                        <th style={{padding:'5px 10px',textAlign:'left',color:'var(--muted)',fontWeight:600}}>Odds range</th>
                        <th style={{padding:'5px 10px',textAlign:'right',color:'var(--muted)',fontWeight:600}}>Suggested</th>
                      </tr>
                    </thead>
                    <tbody>
                      {SCALE_ROWS.map(([range, unit], i) => (
                        <tr key={i} style={{
                          borderBottom:i<SCALE_ROWS.length-1?'1px solid rgba(255,255,255,.04)':'none',
                          background:i%2===0?'transparent':'rgba(255,255,255,.02)'}}>
                          <td style={{padding:'5px 10px',color:'var(--text)'}}>{range}</td>
                          <td style={{padding:'5px 10px',textAlign:'right',color:'#38f282',fontWeight:700}}>{unit}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </>
        )}

        {/* ── Calculate button (single-bet modes) ── */}
        {mode !== 'roundrobin' && (<>
        <button onClick={calculate} disabled={!canCalc}
          style={{width:'100%',padding:'10px',borderRadius:7,border:'none',
            cursor:canCalc?'pointer':'default',fontFamily:osw,fontWeight:700,fontSize:13,
            letterSpacing:.5,textTransform:'uppercase',transition:'all .15s',
            background:canCalc?'var(--accent)':'var(--surface2)',
            color:canCalc?'white':'var(--muted)',opacity:canCalc?1:.5,marginBottom:16}}>
          Calculate
        </button>

        {/* ── Result ── */}
        {result && (
          <div style={{background:'var(--surface2)',border:'1px solid var(--border)',
            borderRadius:8,padding:'14px 16px'}}>
            {[
              ['Implied Prob',
               result.impliedProb.toFixed(1) + '%',
               'var(--text)', 13],
              ['Suggested Fraction',
               `${result.unitFrac.toFixed(3)}u of ${sym}${result.fullUnitValue.toFixed(2)}`,
               '#f5a623', 12],
              ['Est. Stake',
               calcFmtCcy(result.estStake, currency),
               '#38f282', 14],
              ['Total Return',
               calcFmtCcy(result.potReturn, currency),
               '#38b8f2', 14],
              ['Profit on Win',
               calcFmtCcy(result.profit, currency),
               '#38f282', 14],
            ].map(([lbl, val, clr, fsz]) => (
              <div key={lbl} style={{display:'flex',justifyContent:'space-between',
                alignItems:'baseline',padding:'6px 0',
                borderBottom:'1px solid rgba(255,255,255,.05)'}}>
                <span style={{fontFamily:mono,fontSize:10,color:'var(--muted)'}}>{lbl}</span>
                <span style={{fontFamily:osw,fontWeight:700,fontSize:fsz,color:clr}}>{val}</span>
              </div>
            ))}
            <div style={{marginTop:12,padding:'7px 10px',borderRadius:6,
              background:'rgba(56,242,130,.06)',border:'1px solid rgba(56,242,130,.18)'}}>
              <span style={{fontFamily:mono,fontSize:9,color:'var(--muted)',textTransform:'uppercase',
                letterSpacing:.5}}>Risk level: </span>
              <span style={{fontFamily:osw,fontWeight:700,fontSize:12,color:'#38f282'}}>{result.desc}</span>
            </div>
            <div style={{fontFamily:mono,fontSize:9,color:'var(--muted)',marginTop:8,lineHeight:1.6}}>
              Floor: {sym}0.10.{mode==='manual'?' Sized to return 1 unit profit.':' Fraction auto-suggested from odds.'}
            </div>
          </div>
        )}
        </>)}

        {/* ── Parlay / Round Robin: Calculate button + Result ── */}
        {mode === 'roundrobin' && rrPickNum>=2 && (
          <>
            <button onClick={calculateRR} disabled={!rrCanCalc}
              style={{width:'100%',padding:'10px',borderRadius:7,border:'none',
                cursor:rrCanCalc?'pointer':'default',fontFamily:osw,fontWeight:700,fontSize:13,
                letterSpacing:.5,textTransform:'uppercase',transition:'all .15s',
                background:rrCanCalc?'var(--accent)':'var(--surface2)',
                color:rrCanCalc?'white':'var(--muted)',opacity:rrCanCalc?1:.5,marginBottom:16}}>
              {rrEnabled && rrPickNum>=3 ? 'Calculate Parlay + Round Robin' : 'Calculate Parlay'}
            </button>

            {/* ── Straight parlay — all picks combined, always shown ── */}
            {parlayResult && (
              <div style={{background:'var(--surface2)',border:'1px solid var(--border)',
                borderRadius:8,padding:'14px 16px',marginBottom:rrResult?16:0}}>
                <div style={{fontFamily:mono,fontSize:9,color:'var(--muted)',textTransform:'uppercase',
                  letterSpacing:.8,marginBottom:8}}>
                  {rrPickNum}-Leg Parlay
                </div>
                {[
                  ['Parlay Odds', `${parlayResult.american>=0?'+':''}${parlayResult.american}  ·  ${parlayResult.decimal.toFixed(2)}`, 'var(--text)', 13],
                  ['Suggested Unit', `${fmtFrac(parlayResult.frac)}u of ${sym}${(parseFloat(unitSize)||0).toFixed(2)}`, '#f5a623', 12],
                  ['Suggested Stake', calcFmtCcy(parlayResult.stake, currency), '#38f282', 14],
                  ['Total Payout', calcFmtCcy(parlayResult.payout, currency), '#38b8f2', 14],
                  ['Profit on Win', calcFmtCcy(parlayResult.profit, currency), '#38f282', 14],
                ].map(([lbl, val, clr, fsz]) => (
                  <div key={lbl} style={{display:'flex',justifyContent:'space-between',
                    alignItems:'baseline',padding:'6px 0',
                    borderBottom:'1px solid rgba(255,255,255,.05)'}}>
                    <span style={{fontFamily:mono,fontSize:10,color:'var(--muted)'}}>{lbl}</span>
                    <span style={{fontFamily:osw,fontWeight:700,fontSize:fsz,color:clr}}>{val}</span>
                  </div>
                ))}
                <div style={{marginTop:10,padding:'6px 10px',borderRadius:6,
                  background:'rgba(56,242,130,.06)',border:'1px solid rgba(56,242,130,.18)'}}>
                  <span style={{fontFamily:mono,fontSize:9,color:'var(--muted)',textTransform:'uppercase',
                    letterSpacing:.5}}>Risk level: </span>
                  <span style={{fontFamily:osw,fontWeight:700,fontSize:11,color:'#38f282'}}>{parlayResult.desc}</span>
                </div>
                <div style={{fontFamily:mono,fontSize:9,color:'var(--muted)',marginTop:8}}>
                  All {rrPickNum} picks must hit for this bet to pay out.
                </div>
              </div>
            )}

            {/* ── Round Robin combo breakdown — add-on, only when enabled ── */}
            {rrResult && (
              <div style={{background:'var(--surface2)',border:'1px solid var(--border)',
                borderRadius:8,padding:'14px 16px'}}>
                {[
                  ['Lines (combinations)', String(rrResult.combos.length), 'var(--text)', 13],
                  ['Total Stake',      calcFmtCcy(rrResult.totalStake, currency), '#38f282', 14],
                  ['Max Payout (all hit)',  calcFmtCcy(rrResult.maxPayout, currency),  '#38b8f2', 14],
                  ['Max Profit (all hit)',  calcFmtCcy(rrResult.maxProfit, currency),  '#38f282', 14],
                  ['Best single line',  calcFmtCcy(rrResult.ceilPayout, currency),  '#f5a623', 12],
                  ['Floor — worst winning line', calcFmtCcy(rrResult.floorPayout, currency), '#f5a623', 12],
                ].map(([lbl, val, clr, fsz]) => (
                  <div key={lbl} style={{display:'flex',justifyContent:'space-between',
                    alignItems:'baseline',padding:'6px 0',
                    borderBottom:'1px solid rgba(255,255,255,.05)'}}>
                    <span style={{fontFamily:mono,fontSize:10,color:'var(--muted)'}}>{lbl}</span>
                    <span style={{fontFamily:osw,fontWeight:700,fontSize:fsz,color:clr}}>{val}</span>
                  </div>
                ))}

                {/* ── Per-line breakdown ── */}
                <div style={{marginTop:12,borderRadius:6,overflow:'hidden',border:'1px solid var(--border)'}}>
                  <table style={{width:'100%',borderCollapse:'collapse',fontFamily:mono,fontSize:10}}>
                    <thead>
                      <tr style={{background:'var(--surface2)'}}>
                        <th style={{padding:'5px 8px',textAlign:'left',color:'var(--muted)',fontWeight:600}}>Line</th>
                        <th style={{padding:'5px 8px',textAlign:'right',color:'var(--muted)',fontWeight:600}}>Odds</th>
                        <th style={{padding:'5px 8px',textAlign:'right',color:'var(--muted)',fontWeight:600}}>Unit</th>
                        <th style={{padding:'5px 8px',textAlign:'right',color:'var(--muted)',fontWeight:600}}>Stake</th>
                        <th style={{padding:'5px 8px',textAlign:'right',color:'var(--muted)',fontWeight:600}}>Payout</th>
                      </tr>
                    </thead>
                    <tbody>
                      {rrResult.combos.map((c, i) => (
                        <tr key={i} style={{
                          borderBottom:i<rrResult.combos.length-1?'1px solid rgba(255,255,255,.04)':'none',
                          background:i%2===0?'transparent':'rgba(255,255,255,.02)'}}>
                          <td style={{padding:'5px 8px',color:'var(--text)'}}>
                            {c.legIdxs.map(idx => `#${idx+1}`).join(' + ')}
                          </td>
                          <td style={{padding:'5px 8px',textAlign:'right',color:'var(--text)'}}>
                            {c.decimal.toFixed(2)}
                          </td>
                          <td style={{padding:'5px 8px',textAlign:'right',color:'#f5a623'}}>
                            {fmtFrac(c.frac)}u
                          </td>
                          <td style={{padding:'5px 8px',textAlign:'right',color:'var(--text)'}}>
                            {calcFmtCcy(c.stake, currency)}
                          </td>
                          <td style={{padding:'5px 8px',textAlign:'right',color:'#38f282',fontWeight:700}}>
                            {calcFmtCcy(c.payout, currency)}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>

                <div style={{fontFamily:mono,fontSize:9,color:'var(--muted)',marginTop:10,lineHeight:1.6}}>
                  Any {rrComboSize} of your {rrPickNum} picks hitting together pays that line — you don't need all {rrPickNum} to win something.
                  Unit column shows each line's suggested stake as a fraction of your Unit Size (e.g. 0.125u = {calcFmtCcy((parseFloat(unitSize)||0)*0.125, currency)} of a {calcFmtCcy(parseFloat(unitSize)||0, currency)} unit).
                </div>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  </>;
}

function YardPicksFeedTab() {
  const mono = "'DM Mono',monospace", osw = "'Oswald',sans-serif";
  const [picks,    setPicks]    = useState([]);
  const [loading,  setLoading]  = useState(true);
  const [error,    setError]    = useState(null);
  const [cursor,   setCursor]   = useState(null);
  const [hasMore,  setHasMore]  = useState(false);
  const [loadingMore, setLoadingMore] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [showYPHelp, setShowYPHelp] = useState(false);
  const [showCalc,   setShowCalc]   = useState(false);

  const fetchPicks = async (startCursor) => {
    try {
      const qs = new URLSearchParams({ pageSize: '25' });
      if (startCursor) qs.set('cursor', startCursor);
      const r = await fetch(`/api/yardpicks?${qs.toString()}`);
      if (!r.ok) throw new Error(`Server returned ${r.status}`);
      const data = await r.json();
      if (data.error) throw new Error(data.error);
      setPicks(prev => startCursor ? [...prev, ...(data.picks||[])] : (data.picks||[]));
      setHasMore(!!data.hasMore);
      setCursor(data.nextCursor || null);
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
      setLoadingMore(false);
    }
  };

  useEffect(() => { fetchPicks(null); }, []);

  const loadMore = () => {
    if (!cursor || loadingMore) return;
    setLoadingMore(true);
    fetchPicks(cursor);
  };

  const refresh = () => {
    if (refreshing) return;
    setRefreshing(true);
    setError(null);
    setCursor(null);
    fetchPicks(null).finally(() => setRefreshing(false));
  };

  return (
    <div style={{maxWidth:480,margin:'0 auto',padding:'4px 0 24px'}}>
      {showYPHelp && <HelpSlideout title="🧾 Yard Picks Guide" onClose={()=>setShowYPHelp(false)} items={[
        ['What is Yard Picks?', "The Going Yard official daily picks feed — curated HR prop picks posted each morning by the PRISM Labs team. Sourced from the engine's top signals each day."],
        ['Pick cards', "Each card shows the batter, pitcher matchup, Yard Score, signal flags, odds, and the reasoning behind the pick. Newest picks appear at the top."],
        ['🧮 Odds Calculator', "Tap the calculator button to open the Odds Calculator slideout. Three modes: Manual (enter odds + stake for payout), Suggested (unit-fraction stake sized by signal strength), and Parlay (2–5 legs, straight parlay by default, with an optional Round Robin combo breakdown — suggested stakes are bankroll-capped so extreme odds never suggest betting more than your full bankroll). Enter odds in American or decimal format."],
        ['Load more', 'Picks load 25 at a time. Tap Load More at the bottom to fetch older picks from the archive.'],
        ['Refresh', 'Tap the refresh button to pull the latest picks without reloading the page.'],
      ]}/>}
      {showCalc && <OddsCalculatorSlideout onClose={()=>setShowCalc(false)}/>}
      <div style={{display:'flex',alignItems:'center',gap:8,padding:'4px 4px 14px'}}>
        <span style={{fontSize:18}}>🧾</span>
        <span style={{fontFamily:osw,fontWeight:800,fontSize:16,color:'var(--text)'}}>Yard Picks</span>
        <button onClick={()=>setShowCalc(c=>!c)} data-tip="Odds Calculator"
          style={{padding:'4px 8px',borderRadius:6,fontSize:14,cursor:'pointer',
            border:'1px solid var(--border)',lineHeight:1,
            background:showCalc?'var(--surface2)':'transparent',color:'var(--text)'}}>
          🧮
        </button>
        <button onClick={refresh} disabled={refreshing} data-tip="Refresh"
          style={{marginLeft:'auto',padding:'4px 10px',borderRadius:6,fontSize:11,
            cursor:refreshing?'default':'pointer',border:'1px solid var(--border)',
            color:'var(--muted)',background:'transparent',fontWeight:700,
            display:'flex',alignItems:'center',gap:5,opacity:refreshing?.6:1}}>
          <span style={{display:'inline-block',transition:'transform .4s',
            transform:refreshing?'rotate(360deg)':'none'}}>↻</span>
          {refreshing ? 'Refreshing…' : 'Refresh'}
        </button>
        <HelpBtn onClick={()=>setShowYPHelp(v=>!v)}/>
      </div>

      {loading && (
        <div className="lw"><div className="sp"/><div className="lt">Loading Yard Picks…</div></div>
      )}

      {!loading && error && (
        <div style={{padding:20,textAlign:'center',color:'var(--accent)',fontFamily:mono,fontSize:12}}>
          Couldn't load Yard Picks: {error}
        </div>
      )}

      {!loading && !error && picks.length === 0 && (
        <div style={{padding:20,textAlign:'center',color:'var(--muted)',fontFamily:mono,fontSize:12}}>
          No picks posted yet.
        </div>
      )}

      {!loading && !error && picks.map(p => (
        <div key={p.id} style={{background:'var(--surface)',border:'1px solid var(--border)',
          borderRadius:10,marginBottom:12,overflow:'hidden'}}>
          {p.imageUrl && (
            <img src={p.imageUrl} alt={p.title||'Yard Pick'} loading="lazy"
              style={{width:'100%',display:'block',maxHeight:480,objectFit:'contain',background:'#000'}}/>
          )}
          <div style={{padding:'10px 14px'}}>
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'baseline',marginBottom:4}}>
              <span style={{fontFamily:osw,fontWeight:700,fontSize:13,color:'var(--text)'}}>
                {p.title || 'Yard Pick'}
              </span>
              {p.relativeTime && (
                <span style={{fontFamily:mono,fontSize:10,color:'var(--muted)',whiteSpace:'nowrap'}}>
                  {p.relativeTime}
                </span>
              )}
            </div>
            {(p.estPostTime || p.date) && (
              <div style={{fontFamily:mono,fontSize:10,color:'var(--muted)',marginBottom:8}}>
                {p.estPostTime}{p.estPostTime && p.date ? ' · ' : ''}{p.date}
              </div>
            )}
            {p.gamblyLink && (
              <a href={p.gamblyLink} target="_blank" rel="noopener noreferrer"
                style={{display:'inline-flex',alignItems:'center',gap:5,padding:'6px 12px',
                  borderRadius:6,background:'var(--accent)',color:'white',textDecoration:'none',
                  fontFamily:osw,fontWeight:700,fontSize:11,letterSpacing:.5}}>
                ↗ Open Gambly Slip
              </a>
            )}
          </div>
        </div>
      ))}

      {!loading && !error && hasMore && (
        <div style={{textAlign:'center',marginTop:6}}>
          <button onClick={loadMore} disabled={loadingMore}
            style={{padding:'8px 20px',borderRadius:7,cursor:loadingMore?'default':'pointer',
              border:'1px solid var(--border)',background:'var(--surface2)',color:'var(--muted)',
              fontFamily:osw,fontWeight:700,fontSize:11,letterSpacing:.5,opacity:loadingMore?.6:1}}>
            {loadingMore ? 'Loading…' : 'Load More'}
          </button>
        </div>
      )}
    </div>
  );
}

